-- auto-apply
-- Shared AI caches become server-write only. Readers' browsers save through
-- the cache-write Edge Function (service role, fill-only, validated,
-- rate-limited); they can no longer insert/update these tables directly.
-- article_study_content is generated by the admin only, so learners lose
-- write access there too. Admin keeps direct writes from the CMS with the
-- admin's own session (is_admin_email). Idempotent.

-- True/False comprehension check cache (was written to a column that didn't
-- exist, so every visit paid for a new AI call).
alter table public.article_cache add column if not exists tf_v1 text;

-- Per-user save log for cache-write's hourly limit. Service role only.
create table if not exists public.cache_write_log (
  id bigserial primary key,
  user_id uuid not null,
  tbl text not null,
  cache_key text,
  created_at timestamptz not null default now()
);
create index if not exists cache_write_log_user_time on public.cache_write_log (user_id, created_at desc);
alter table public.cache_write_log enable row level security;

-- article_cache
drop policy if exists "article_cache auth write"  on public.article_cache;
drop policy if exists "article_cache auth update" on public.article_cache;
drop policy if exists "article_cache admin write" on public.article_cache;
create policy "article_cache admin write" on public.article_cache
  for all to authenticated using (public.is_admin_email()) with check (public.is_admin_email());

-- grammar_examples_cache
drop policy if exists "grammar_examples_cache auth insert" on public.grammar_examples_cache;
drop policy if exists "grammar_examples_cache auth update" on public.grammar_examples_cache;
drop policy if exists "grammar_examples_cache admin write" on public.grammar_examples_cache;
create policy "grammar_examples_cache admin write" on public.grammar_examples_cache
  for all to authenticated using (public.is_admin_email()) with check (public.is_admin_email());

-- article_study_content (replaces the learner policies from 20261028_shared_cache_guard.sql)
drop policy if exists asc_auth_insert  on public.article_study_content;
drop policy if exists asc_auth_update  on public.article_study_content;
drop policy if exists asc_admin_delete on public.article_study_content;
drop policy if exists asc_admin_write  on public.article_study_content;
create policy asc_admin_write on public.article_study_content
  for all to authenticated using (public.is_admin_email()) with check (public.is_admin_email());

-- Service-role writes (cache-write, content-qa) set written_by themselves or
-- leave the column alone; only signed-in sessions are stamped here.
create or replace function public.kh_cache_stamp_writer()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if auth.uid() is null then return new; end if;
  if not public.is_admin_email() and octet_length(to_jsonb(new)::text) > 1048576 then
    raise exception 'cache row too large' using errcode = '22001';
  end if;
  new.written_by := auth.uid();
  return new;
end;
$$;
